tool_input.command:
$r = Invoke-RestMethod -Uri 'http://127.0.0.1:3425/v1/models' -TimeoutSec 8
$all = $r.data | ForEach-Object { $_.id }
"网关模型总数: $($all.Count)"
"=== 按 provider ==="
$all | ForEach-Object { ($_ -split '/')[0] } | Group-Object | Sort-Object Name | ForEach-Object { "  {0}: {1}" -f $_.Name,$_.Count }
